  `installation_date` date DEFAULT NULL,
  PRIMARY KEY (`battery_log_id`),
  KEY `asset_id` (`asset_id`),
  CONSTRAINT `battery_logs_ibfk_1` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`asset_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
